"""Tokenizer and recursive-descent parser for minisql. See SPEC.md, "Syntax".

``parse(sql)`` turns a query string into a :class:`minisql.ast.Query`, raising
:class:`minisql.errors.QueryError` for any lexical or syntax error.

Notes on choices the spec leaves open:

* Comparisons don't chain: ``a = b = c`` (or ``a IS NULL = TRUE``) is a
  syntax error; parenthesise to combine them, e.g. ``(a = b) = c``.
* A number must not run straight into a name character or a dot
  (``5abc``, ``1.2.3``), which is a lexical error rather than ``5 AS abc``.
* Unary minus is never constant-folded: ``-5`` is ``Unary('-', Literal(5))``.
"""

from .ast import (
    Between,
    Binary,
    Call,
    Column,
    In,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Query,
    SelectItem,
    Unary,
)
from .errors import QueryError

__all__ = ["parse"]

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

# Token kinds.
NAME = "name"  # unquoted identifier (not a keyword)
QNAME = "quoted name"
KEYWORD = "keyword"
INT = "integer"
FLOAT = "decimal"
STRING = "string"
OP = "operator"
EOF = "end of input"

_TWO_CHAR_OPS = ("<=", ">=", "<>", "!=", "||")
_ONE_CHAR_OPS = "=<>+-*/(),;"
_COMPARISON_OPS = ("=", "!=", "<>", "<", "<=", ">", ">=")


class Token:
    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        self.kind = kind
        self.value = value  # keyword: upper-cased; names/strings: unquoted
        self.start = start
        self.end = end

    def __repr__(self):
        return "Token(%s, %r, %d, %d)" % (self.kind, self.value, self.start, self.end)


def _is_name_start(c):
    return c == "_" or ("a" <= c <= "z") or ("A" <= c <= "Z")


def _is_name_char(c):
    return _is_name_start(c) or ("0" <= c <= "9")


def _is_digit(c):
    return "0" <= c <= "9"


def tokenize(sql):
    """Split ``sql`` into a list of tokens ending with an EOF token."""
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if _is_name_start(c):
            while i < n and _is_name_char(sql[i]):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token(KEYWORD, upper, start, i))
            else:
                tokens.append(Token(NAME, word, start, i))
        elif c == '"' or c == "'":
            value, i = _read_quoted(sql, i, c)
            tokens.append(Token(QNAME if c == '"' else STRING, value, start, i))
        elif _is_digit(c) or (c == "." and i + 1 < n and _is_digit(sql[i + 1])):
            while i < n and _is_digit(sql[i]):
                i += 1
            is_float = False
            if i < n and sql[i] == ".":
                is_float = True
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            if i < n and (_is_name_char(sql[i]) or sql[i] == "."):
                raise QueryError(
                    "invalid number %r at position %d"
                    % (sql[start : i + 1], start + 1)
                )
            text = sql[start:i]
            if is_float:
                tokens.append(Token(FLOAT, float(text), start, i))
            else:
                tokens.append(Token(INT, int(text), start, i))
        elif sql[i : i + 2] in _TWO_CHAR_OPS:
            i += 2
            tokens.append(Token(OP, sql[start:i], start, i))
        elif c in _ONE_CHAR_OPS:
            i += 1
            tokens.append(Token(OP, c, start, i))
        else:
            raise QueryError(
                "unexpected character %r at position %d" % (c, start + 1)
            )
    tokens.append(Token(EOF, None, n, n))
    return tokens


def _read_quoted(sql, i, quote):
    """Read a quoted string/name starting at ``sql[i] == quote``, with the
    quote doubled as its escape. Return (value, index after closing quote)."""
    start = i
    i += 1
    parts = []
    n = len(sql)
    while True:
        j = sql.find(quote, i)
        if j < 0:
            what = "string" if quote == "'" else "quoted name"
            raise QueryError(
                "unterminated %s starting at position %d" % (what, start + 1)
            )
        parts.append(sql[i:j])
        if j + 1 < n and sql[j + 1] == quote:
            parts.append(quote)
            i = j + 2
        else:
            return "".join(parts), j + 1


def _describe(tok):
    if tok.kind == EOF:
        return "end of input"
    return repr(tok.value if tok.kind == KEYWORD else _raw(tok))


def _raw(tok):
    return _Parser.current_sql[tok.start : tok.end]


class _Parser:
    current_sql = ""  # for error messages only; set per parse

    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0
        # id(node) -> (start, end) source offsets of the node's text.
        self.spans = {}

    # ----- token helpers -------------------------------------------------

    @property
    def tok(self):
        return self.tokens[self.pos]

    def peek(self, offset=1):
        idx = min(self.pos + offset, len(self.tokens) - 1)
        return self.tokens[idx]

    def advance(self):
        tok = self.tokens[self.pos]
        if tok.kind != EOF:
            self.pos += 1
        return tok

    def is_kw(self, *words, tok=None):
        tok = tok or self.tok
        return tok.kind == KEYWORD and tok.value in words

    def is_op(self, *ops, tok=None):
        tok = tok or self.tok
        return tok.kind == OP and tok.value in ops

    def accept_kw(self, word):
        if self.is_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.is_op(op):
            return self.advance()
        return None

    def error(self, expected, tok=None):
        tok = tok or self.tok
        if tok.kind == EOF:
            where = "at end of input"
        else:
            where = "at position %d near %s" % (tok.start + 1, _describe(tok))
        return QueryError("syntax error %s: expected %s" % (where, expected))

    def expect_kw(self, word):
        if not self.is_kw(word):
            raise self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.is_op(op):
            raise self.error("'%s'" % op)
        return self.advance()

    def expect_name(self, what):
        tok = self.tok
        if tok.kind in (NAME, QNAME):
            return self.advance().value
        if tok.kind == KEYWORD:
            raise self.error(
                "%s (%s is a keyword; double-quote it to use it as a name)"
                % (what, tok.value)
            )
        raise self.error(what)

    # ----- node helpers --------------------------------------------------

    def node(self, node, start, end):
        """Record ``node``'s span and set its text to that source slice."""
        node.text = self.sql[start:end]
        self.spans[id(node)] = (start, end)
        return node

    def start_of(self, node):
        return self.spans[id(node)][0]

    def end_of(self, node):
        return self.spans[id(node)][1]

    # ----- query ---------------------------------------------------------

    def parse_query(self):
        if self.tok.kind == EOF:
            raise QueryError("empty query")
        self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT") is not None

        if self.is_op("*"):
            self.advance()
            items = None
        else:
            items = [self.parse_select_item()]
            while self.accept_op(","):
                items.append(self.parse_select_item())

        self.expect_kw("FROM")
        table = self.expect_name("table name")
        query = Query(table=table, items=items, distinct=distinct)

        if self.accept_kw("WHERE"):
            query.where = self.parse_expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            query.group_by = [self.parse_expr()]
            while self.accept_op(","):
                query.group_by.append(self.parse_expr())
        if self.accept_kw("HAVING"):
            query.having = self.parse_expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            query.order_by = [self.parse_order_item()]
            while self.accept_op(","):
                query.order_by.append(self.parse_order_item())
        if self.accept_kw("LIMIT"):
            query.limit = self.parse_count("LIMIT")
            if self.accept_kw("OFFSET"):
                query.offset = self.parse_count("OFFSET")

        self.accept_op(";")
        if self.tok.kind != EOF:
            raise self.error("end of query")
        return query

    def parse_select_item(self):
        expr = self.parse_expr()
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name("column alias after AS")
        elif self.tok.kind in (NAME, QNAME):
            alias = self.advance().value
        return SelectItem(expr, alias)

    def parse_order_item(self):
        expr = self.parse_expr()
        descending = False
        if self.accept_kw("DESC"):
            descending = True
        else:
            self.accept_kw("ASC")
        return OrderItem(expr, descending)

    def parse_count(self, clause):
        if self.tok.kind != INT:
            raise self.error("a non-negative integer after %s" % clause)
        return self.advance().value

    # ----- expressions ---------------------------------------------------

    def parse_expr(self):
        return self.parse_or()

    def _binary(self, op, left, right):
        return self.node(
            Binary(op, left, right), self.start_of(left), self.end_of(right)
        )

    def parse_or(self):
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = self._binary("OR", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = self._binary("AND", left, self.parse_not())
        return left

    def parse_not(self):
        if self.is_kw("NOT"):
            start = self.advance().start
            operand = self.parse_not()
            return self.node(Unary("NOT", operand), start, self.end_of(operand))
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        start = self.start_of(left)
        result = None

        if self.is_kw("IS"):
            self.advance()
            negated = self.accept_kw("NOT") is not None
            end = self.expect_kw("NULL").end
            result = self.node(IsNull(left, negated), start, end)
        elif self.tok.kind == OP and self.tok.value in _COMPARISON_OPS:
            op = self.advance().value
            if op == "<>":
                op = "!="
            right = self.parse_additive()
            result = self._binary(op, left, right)
        else:
            negated = False
            if self.is_kw("NOT") and self.is_kw("IN", "BETWEEN", "LIKE", tok=self.peek()):
                self.advance()
                negated = True
            if self.accept_kw("IN"):
                self.expect_op("(")
                items = [self.parse_expr()]
                while self.accept_op(","):
                    items.append(self.parse_expr())
                end = self.expect_op(")").end
                result = self.node(In(left, items, negated), start, end)
            elif self.accept_kw("BETWEEN"):
                low = self.parse_additive()
                self.expect_kw("AND")
                high = self.parse_additive()
                result = self.node(
                    Between(left, low, high, negated), start, self.end_of(high)
                )
            elif self.accept_kw("LIKE"):
                pattern = self.parse_additive()
                result = self.node(
                    Like(left, pattern, negated), start, self.end_of(pattern)
                )
            elif self.is_kw("NOT"):
                raise self.error("IN, BETWEEN or LIKE after NOT", self.peek())

        if result is None:
            return left
        tok = self.tok
        if (
            (tok.kind == OP and tok.value in _COMPARISON_OPS)
            or self.is_kw("IS", "IN", "BETWEEN", "LIKE")
            or (self.is_kw("NOT") and self.is_kw("IN", "BETWEEN", "LIKE", tok=self.peek()))
        ):
            raise QueryError(
                "syntax error at position %d near %s: comparisons can't be "
                "chained; use parentheses" % (tok.start + 1, _describe(tok))
            )
        return result

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.is_op("+", "-", "||"):
            op = self.advance().value
            left = self._binary(op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.is_op("*", "/"):
            op = self.advance().value
            left = self._binary(op, left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.is_op("-"):
            start = self.advance().start
            operand = self.parse_unary()
            return self.node(Unary("-", operand), start, self.end_of(operand))
        return self.parse_primary()

    def parse_primary(self):
        tok = self.tok
        if tok.kind in (INT, FLOAT, STRING):
            self.advance()
            return self.node(Literal(tok.value), tok.start, tok.end)
        if tok.kind == KEYWORD and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            value = {"NULL": None, "TRUE": True, "FALSE": False}[tok.value]
            return self.node(Literal(value), tok.start, tok.end)
        if tok.kind == NAME and self.is_op("(", tok=self.peek()):
            return self.parse_call()
        if tok.kind in (NAME, QNAME):
            self.advance()
            return self.node(Column(tok.value), tok.start, tok.end)
        if self.is_op("("):
            start = self.advance().start
            inner = self.parse_expr()
            end = self.expect_op(")").end
            # The parentheses belong to the inner expression's text.
            return self.node(inner, start, end)
        if tok.kind == KEYWORD:
            raise self.error(
                "an expression (%s is a keyword; double-quote it to use it "
                "as a name)" % tok.value
            )
        raise self.error("an expression")

    def parse_call(self):
        name_tok = self.advance()
        name = name_tok.value.upper()
        self.expect_op("(")
        args = []
        star = False
        if self.is_op("*"):
            if name != "COUNT":
                raise self.error("an argument (only COUNT accepts *)")
            self.advance()
            star = True
        elif not self.is_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        end = self.expect_op(")").end
        return self.node(Call(name, args, star), name_tok.start, end)


def parse(sql):
    """Parse ``sql`` into a :class:`minisql.ast.Query`."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    _Parser.current_sql = sql
    return _Parser(sql).parse_query()

