"""Evaluate a parsed query (see ``ast.py``) against a directory of CSV files."""

import csv
import functools
import math
import os
import re
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

from . import ast
from .errors import QueryError

__all__ = ["Result", "execute"]


class Result:
    """The result of a query: ``columns`` (names) and ``rows`` (tuples)."""

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)

    def __repr__(self):
        return "Result(columns={!r}, rows={!r})".format(self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows

    __hash__ = None


# ---------------------------------------------------------------- loading

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


class _Table:
    def __init__(self, header, rows):
        self.header = header
        self.rows = rows
        self.index = {}
        for i, name in enumerate(header):
            self.index.setdefault(name.lower(), i)  # first one wins

    def lookup(self, column):
        try:
            return self.index[column.key]
        except KeyError:
            raise QueryError("unknown column: {}".format(column.name)) from None


def _load_table(directory, name):
    path = os.path.join(directory, name + ".csv")
    if not name or not os.path.isfile(path):
        raise QueryError("unknown table: {}".format(name))
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                raise QueryError("table {} has no header".format(name))
            rows = []
            for record in reader:
                if not record:
                    continue  # blank line
                if len(record) != len(header):
                    raise QueryError(
                        "table {}, line {}: expected {} fields, got {}".format(
                            name, reader.line_num, len(header), len(record)
                        )
                    )
                rows.append(tuple(_convert(v) for v in record))
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table {}: {}".format(name, e)) from None
    return _Table(header, rows)


# ---------------------------------------------------------------- helpers

AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
# name -> (min args, max args or None for unlimited)
SCALARS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


def _children(expr):
    if isinstance(expr, (ast.Literal, ast.Column)):
        return []
    if isinstance(expr, ast.Unary):
        return [expr.operand]
    if isinstance(expr, ast.Binary):
        return [expr.left, expr.right]
    if isinstance(expr, ast.IsNull):
        return [expr.operand]
    if isinstance(expr, ast.In):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, ast.Between):
        return [expr.operand, expr.low, expr.high]
    if isinstance(expr, ast.Like):
        return [expr.operand, expr.pattern]
    if isinstance(expr, ast.Call):
        return list(expr.args)
    raise QueryError("unsupported expression: {!r}".format(expr))


def _walk(expr):
    yield expr
    for child in _children(expr):
        yield from _walk(child)


def _is_aggregate(expr):
    return isinstance(expr, ast.Call) and expr.name.upper() in AGGREGATES


def _has_aggregate(expr):
    return any(_is_aggregate(e) for e in _walk(expr))


def _type_name(v):
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, (int, float)):
        return "number"
    if isinstance(v, str):
        return "string"
    return type(v).__name__


def _is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _text(v):
    """Text of a value for ``||``."""
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)


def _value_key(v):
    """A hashable key that is equal exactly when values are SQL-equal
    (so TRUE and 1 differ, while 1 and 1.0 are the same)."""
    if v is None:
        return (0,)
    if isinstance(v, bool):
        return (1, v)
    if isinstance(v, (int, float)):
        return (2, v)
    return (3, v)


def _check_comparable(a, b, what="compare"):
    ta, tb = _type_name(a), _type_name(b)
    if ta != tb:
        raise QueryError("cannot {} {} with {}".format(what, ta, tb))


def _compare(a, b):
    """Three-way compare of two non-NULL values of compatible types."""
    _check_comparable(a, b)
    return (a > b) - (a < b)


def _check_bool(v, op):
    if v is not None and not isinstance(v, bool):
        raise QueryError("{} needs boolean operands, got {}".format(op, _type_name(v)))


def _round_half_away(x, places):
    if isinstance(x, int):
        d = Decimal(x)
    else:
        if not math.isfinite(x):
            return x
        d = Decimal(repr(x))
    try:
        return d.quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_UP)
    except InvalidOperation:
        raise QueryError("ROUND: value out of range") from None


_LIKE_CACHE = {}


def _like_regex(pattern):
    rx = _LIKE_CACHE.get(pattern)
    if rx is None:
        parts = []
        for ch in pattern:
            if ch == "%":
                parts.append(".*")
            elif ch == "_":
                parts.append(".")
            else:
                parts.append(re.escape(ch))
        rx = re.compile("".join(parts), re.DOTALL)
        _LIKE_CACHE[pattern] = rx
    return rx


# ---------------------------------------------------------------- evaluation


class _Context:
    """What an expression is evaluated against: a single input row, or a
    group (a representative row plus all of the group's rows)."""

    __slots__ = ("row", "group")

    def __init__(self, row, group=None):
        self.row = row
        self.group = group


class _Evaluator:
    def __init__(self, table):
        self.table = table

    def eval(self, expr, ctx):
        method = getattr(self, "_eval_" + type(expr).__name__, None)
        if method is None:
            raise QueryError("unsupported expression: {!r}".format(expr))
        return method(expr, ctx)

    def _eval_Literal(self, expr, ctx):
        return expr.value

    def _eval_Column(self, expr, ctx):
        if ctx.row is None:
            # Only reachable for an empty group without GROUP BY, which
            # validation rules out; kept as a safety net.
            raise QueryError("column {} is not grouped".format(expr.name))
        return ctx.row[self.table.lookup(expr)]

    def _eval_Unary(self, expr, ctx):
        v = self.eval(expr.operand, ctx)
        op = expr.op.upper()
        if op == "NOT":
            _check_bool(v, "NOT")
            return None if v is None else not v
        if op == "-":
            if v is None:
                return None
            if not _is_number(v):
                raise QueryError("cannot negate {}".format(_type_name(v)))
            return -v
        raise QueryError("unknown operator: {}".format(expr.op))

    def _eval_Binary(self, expr, ctx):
        op = expr.op.upper()
        if op == "<>":
            op = "!="
        a = self.eval(expr.left, ctx)
        b = self.eval(expr.right, ctx)
        if op == "AND":
            _check_bool(a, "AND")
            _check_bool(b, "AND")
            if a is False or b is False:
                return False
            if a is None or b is None:
                return None
            return True
        if op == "OR":
            _check_bool(a, "OR")
            _check_bool(b, "OR")
            if a is True or b is True:
                return True
            if a is None or b is None:
                return None
            return False
        if op == "||":
            if a is None or b is None:
                return None
            return _text(a) + _text(b)
        if op in ("+", "-", "*", "/"):
            return self._arith(op, a, b)
        if op in ("=", "!=", "<", "<=", ">", ">="):
            return self._comparison(op, a, b)
        raise QueryError("unknown operator: {}".format(expr.op))

    @staticmethod
    def _arith(op, a, b):
        for v in (a, b):
            if v is not None and not _is_number(v):
                raise QueryError(
                    "arithmetic ({}) on {}".format(op, _type_name(v))
                )
        if a is None or b is None:
            return None
        try:
            if op == "+":
                r = a + b
            elif op == "-":
                r = a - b
            elif op == "*":
                r = a * b
            else:
                if b == 0:
                    return None
                return a / b
        except OverflowError:
            raise QueryError("arithmetic overflow") from None
        if isinstance(a, int) and isinstance(b, int):
            return r
        return float(r)

    @staticmethod
    def _comparison(op, a, b):
        if a is not None and b is not None:
            _check_comparable(a, b)
        else:
            return None
        if op == "=":
            return a == b
        if op == "!=":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b

    def _eval_IsNull(self, expr, ctx):
        v = self.eval(expr.operand, ctx)
        return (v is not None) if expr.negated else (v is None)

    def _eval_In(self, expr, ctx):
        x = self.eval(expr.operand, ctx)
        items = [self.eval(item, ctx) for item in expr.items]
        found = False
        saw_null = x is None
        for item in items:
            if item is None:
                saw_null = True
            elif x is not None:
                _check_comparable(x, item)
                if x == item:
                    found = True
        if found:
            result = True
        elif saw_null:
            result = None
        else:
            result = False
        if expr.negated and result is not None:
            result = not result
        return result

    def _eval_Between(self, expr, ctx):
        x = self.eval(expr.operand, ctx)
        low = self.eval(expr.low, ctx)
        high = self.eval(expr.high, ctx)
        lo_ok = self._comparison("<=", low, x)
        hi_ok = self._comparison("<=", x, high)
        if lo_ok is False or hi_ok is False:
            result = False
        elif lo_ok is None or hi_ok is None:
            result = None
        else:
            result = True
        if expr.negated and result is not None:
            result = not result
        return result

    def _eval_Like(self, expr, ctx):
        s = self.eval(expr.operand, ctx)
        p = self.eval(expr.pattern, ctx)
        for v in (s, p):
            if v is not None and not isinstance(v, str):
                raise QueryError("LIKE needs strings, got {}".format(_type_name(v)))
        if s is None or p is None:
            return None
        result = _like_regex(p).fullmatch(s) is not None
        return (not result) if expr.negated else result

    def _eval_Call(self, expr, ctx):
        name = expr.name.upper()
        if name in AGGREGATES:
            return self._aggregate(name, expr, ctx)
        args = [self.eval(a, ctx) for a in expr.args]
        if name == "COALESCE":
            for v in args:
                if v is not None:
                    return v
            return None
        x = args[0]
        if name in ("LOWER", "UPPER", "LENGTH"):
            if x is not None and not isinstance(x, str):
                raise QueryError("{} needs a string, got {}".format(name, _type_name(x)))
            if x is None:
                return None
            if name == "LOWER":
                return x.lower()
            if name == "UPPER":
                return x.upper()
            return len(x)
        if name == "ABS":
            if x is not None and not _is_number(x):
                raise QueryError("ABS needs a number, got {}".format(_type_name(x)))
            return None if x is None else abs(x)
        if name == "ROUND":
            if x is not None and not _is_number(x):
                raise QueryError("ROUND needs a number, got {}".format(_type_name(x)))
            if len(args) == 1:
                if x is None:
                    return None
                if isinstance(x, int):
                    return x
                if not math.isfinite(x):
                    raise QueryError("ROUND: value out of range")
                return int(_round_half_away(x, 0))
            n = args[1]
            if n is not None and (not isinstance(n, int) or isinstance(n, bool)):
                raise QueryError(
                    "ROUND needs an integer number of places, got {}".format(
                        _type_name(n) if not isinstance(n, float) else "decimal"
                    )
                )
            if x is None or n is None:
                return None
            r = _round_half_away(x, n)
            return float(r)
        raise QueryError("unknown function: {}".format(expr.name))

    def _aggregate(self, name, expr, ctx):
        if ctx.group is None:
            raise QueryError("aggregate {} not allowed here".format(name))
        rows = ctx.group
        if expr.star:
            return len(rows)
        arg = expr.args[0]
        values = []
        for row in rows:
            v = self.eval(arg, _Context(row))
            if v is not None:
                values.append(v)
        if name == "COUNT":
            return len(values)
        if not values:
            return None
        if name in ("SUM", "AVG"):
            for v in values:
                if not _is_number(v):
                    raise QueryError("{} needs numbers, got {}".format(name, _type_name(v)))
            try:
                if name == "SUM":
                    if all(isinstance(v, int) for v in values):
                        return sum(values)
                    return math.fsum(values)
                if all(isinstance(v, int) for v in values):
                    return sum(values) / len(values)
                return math.fsum(values) / len(values)
            except OverflowError:
                raise QueryError("arithmetic overflow") from None
        # MIN / MAX
        best = values[0]
        for v in values[1:]:
            c = _compare(v, best)
            if (c < 0) if name == "MIN" else (c > 0):
                best = v
        return best


# ---------------------------------------------------------------- validation


def _validate_expr(expr, table, allow_aggregates, where):
    """Check columns exist, functions exist with the right arity, and
    aggregates appear only where allowed and are not nested."""
    for node in _walk(expr):
        if isinstance(node, ast.Column):
            table.lookup(node)
        elif isinstance(node, ast.Call):
            name = node.name.upper()
            if name in AGGREGATES:
                if not allow_aggregates:
                    raise QueryError("aggregate {} not allowed in {}".format(name, where))
                if node.star:
                    if name != "COUNT" or node.args:
                        raise QueryError("{}(*) is not allowed".format(name))
                elif len(node.args) != 1:
                    raise QueryError(
                        "{} takes 1 argument, got {}".format(name, len(node.args))
                    )
                for arg in node.args:
                    if _has_aggregate(arg):
                        raise QueryError("aggregates can't be nested")
            elif name in SCALARS:
                if node.star:
                    raise QueryError("{}(*) is not allowed".format(name))
                lo, hi = SCALARS[name]
                n = len(node.args)
                if n < lo or (hi is not None and n > hi):
                    if lo == hi:
                        want = str(lo)
                    elif hi is None:
                        want = "at least {}".format(lo)
                    else:
                        want = "{} to {}".format(lo, hi)
                    raise QueryError(
                        "{} takes {} argument{}, got {}".format(
                            name, want, "" if want == "1" else "s", n
                        )
                    )
            else:
                raise QueryError("unknown function: {}".format(node.name))


def _check_grouped(expr, group_by):
    """In a grouped query, every column outside an aggregate must lie inside
    a subexpression equal to a GROUP BY expression."""
    if any(expr == g for g in group_by):
        return
    if _is_aggregate(expr):
        return
    if isinstance(expr, ast.Column):
        raise QueryError(
            "column {} must appear in GROUP BY or be used in an aggregate".format(
                expr.name
            )
        )
    for child in _children(expr):
        _check_grouped(child, group_by)


# ---------------------------------------------------------------- execution


def _sort_compare(a, b):
    """Compare two sort-key tuples of (value, descending) pairs."""
    for (x, desc), (y, _) in zip(a, b):
        if x is None and y is None:
            c = 0
        elif x is None:
            c = -1  # NULL first ascending (reversed below for DESC)
        elif y is None:
            c = 1
        else:
            c = _compare(x, y)
        if desc:
            c = -c
        if c:
            return c
    return 0


def execute(query, directory):
    """Run a parsed ``Query`` against the CSV files in ``directory``."""
    table = _load_table(directory, query.table)
    ev = _Evaluator(table)

    # ---- output columns
    if query.items is None:
        star = True
        items = [ast.SelectItem(ast.Column(name, name)) for name in table.header]
        columns = list(table.header)
    else:
        star = False
        items = list(query.items)
        columns = []
        for item in items:
            if item.alias is not None:
                columns.append(item.alias)
            elif isinstance(item.expr, ast.Column):
                columns.append(table.header[table.lookup(item.expr)])
            else:
                columns.append(item.expr.text)

    # ---- resolve ORDER BY items: ("out", index) or ("expr", expr)
    lowered = [c.lower() for c in columns]
    order = []
    for oi in query.order_by:
        e = oi.expr
        if isinstance(e, ast.Column) and e.key in lowered:
            order.append(("out", lowered.index(e.key), oi.descending))
        elif (
            isinstance(e, ast.Literal)
            and isinstance(e.value, int)
            and not isinstance(e.value, bool)
        ):
            n = e.value
            if not 1 <= n <= len(columns):
                raise QueryError("ORDER BY position {} is out of range".format(n))
            order.append(("out", n - 1, oi.descending))
        else:
            order.append(("expr", e, oi.descending))
    order_exprs = [o[1] for o in order if o[0] == "expr"]

    # ---- static validation
    if query.where is not None:
        _validate_expr(query.where, table, False, "WHERE")
    for g in query.group_by:
        _validate_expr(g, table, False, "GROUP BY")
    for item in items:
        _validate_expr(item.expr, table, True, "SELECT")
    if query.having is not None:
        _validate_expr(query.having, table, True, "HAVING")
    for e in order_exprs:
        _validate_expr(e, table, True, "ORDER BY")

    grouped = bool(query.group_by) or any(
        _has_aggregate(e)
        for e in [i.expr for i in items]
        + ([query.having] if query.having is not None else [])
        + order_exprs
    )
    if grouped:
        if star:
            raise QueryError("SELECT * is not allowed in a grouped query")
        for e in [i.expr for i in items] + order_exprs + (
            [query.having] if query.having is not None else []
        ):
            _check_grouped(e, query.group_by)

    for name, value in (("LIMIT", query.limit), ("OFFSET", query.offset)):
        if value is not None and (
            not isinstance(value, int) or isinstance(value, bool) or value < 0
        ):
            raise QueryError("{} must be a non-negative integer".format(name))

    def condition(expr, ctx, where):
        v = ev.eval(expr, ctx)
        if v is not None and not isinstance(v, bool):
            raise QueryError("{} condition must be boolean, got {}".format(where, _type_name(v)))
        return v is True

    # ---- WHERE
    rows = table.rows
    if query.where is not None:
        rows = [r for r in rows if condition(query.where, _Context(r), "WHERE")]

    # ---- grouping: build evaluation contexts
    if grouped:
        if query.group_by:
            groups = {}
            for r in rows:
                ctx = _Context(r)
                key = tuple(_value_key(ev.eval(g, ctx)) for g in query.group_by)
                if key in groups:
                    groups[key].append(r)
                else:
                    groups[key] = [r]
            contexts = [_Context(g[0], g) for g in groups.values()]
        else:
            contexts = [_Context(rows[0] if rows else None, rows)]
    else:
        contexts = [_Context(r) for r in rows]

    # ---- HAVING
    if query.having is not None:
        contexts = [c for c in contexts if condition(query.having, c, "HAVING")]

    # ---- project, computing sort keys alongside
    output = []
    for ctx in contexts:
        values = tuple(ev.eval(item.expr, ctx) for item in items)
        keys = None
        if order:
            keys = tuple(
                (values[o[1]] if o[0] == "out" else ev.eval(o[1], ctx), o[2])
                for o in order
            )
        output.append((values, keys))

    # ---- DISTINCT (keeps the first occurrence, with its sort keys)
    if query.distinct:
        seen = set()
        unique = []
        for values, keys in output:
            k = tuple(_value_key(v) for v in values)
            if k not in seen:
                seen.add(k)
                unique.append((values, keys))
        output = unique

    # ---- ORDER BY
    if order:
        output.sort(key=functools.cmp_to_key(lambda a, b: _sort_compare(a[1], b[1])))

    result_rows = [values for values, _ in output]

    # ---- OFFSET / LIMIT
    if query.offset:
        result_rows = result_rows[query.offset:]
    if query.limit is not None:
        result_rows = result_rows[: query.limit]

    return Result(columns, result_rows)

